#!/usr/bin/env bash
#
# Copyright (C) 2026 The LineageOS / AxionOS Project
#
# setup-makefiles.sh - Generate Vendor Makefiles for Casper VIA S48 (MT8168)
#

set -euo pipefail

VENDOR_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROPRIETARY_LIST="${VENDOR_ROOT}/proprietary-files.txt"
PROPRIETARY_DIR="${VENDOR_ROOT}/proprietary"
OUTPUT_MK="${VENDOR_ROOT}/via_s48-vendor.mk"
BOARD_MK="${VENDOR_ROOT}/BoardConfigVendor.mk"

cat << 'EOF' > "${BOARD_MK}"
#
# Copyright (C) 2026 The LineageOS / AxionOS Project
#
# BoardConfigVendor for Casper VIA S48 (MT8168 / F716)
# Automatically generated by setup-makefiles.sh. DO NOT MODIFY.
#

# Vendor Soong Namespace
PRODUCT_SOONG_NAMESPACES += vendor/casper/via_s48
EOF

cat << 'EOF' > "${OUTPUT_MK}"
#
# Copyright (C) 2026 The LineageOS / AxionOS Project
#
# Proprietary blob copy list for Casper VIA S48 (MT8168 / F716)
# Automatically generated by setup-makefiles.sh. DO NOT MODIFY.
#

PRODUCT_SOONG_NAMESPACES += vendor/casper/via_s48

PRODUCT_COPY_FILES += \
EOF

COUNT=0

# If proprietary directory exists and has files, use actual extracted files
# Otherwise, populate from proprietary-files.txt to ensure build makefile is populated
if [[ -d "${PROPRIETARY_DIR}" ]] && [[ $(find "${PROPRIETARY_DIR}" -type f | wc -l) -gt 0 ]]; then
    echo "[*] Populating via_s48-vendor.mk from extracted proprietary/ directory..."
    find "${PROPRIETARY_DIR}" -type f | sort | while read -r f; do
        REL_PATH="${f#${PROPRIETARY_DIR}/}"
        echo "    vendor/casper/via_s48/proprietary/${REL_PATH}:\$(TARGET_COPY_OUT_VENDOR)/${REL_PATH} \\" >> "${OUTPUT_MK}"
        COUNT=$((COUNT + 1))
    done
else
    echo "[*] Populating via_s48-vendor.mk from ${PROPRIETARY_LIST}..."
    while IFS= read -r line || [[ -n "$line" ]]; do
        line="$(echo "${line}" | sed -e 's/^[[:space:]]*//' -e 's/[[:space:]]*$//')"
        [[ -z "$line" || "$line" =~ ^# ]] && continue

        echo "    vendor/casper/via_s48/proprietary/${line}:\$(TARGET_COPY_OUT_VENDOR)/${line} \\" >> "${OUTPUT_MK}"
        COUNT=$((COUNT + 1))
    done < "${PROPRIETARY_LIST}"
fi

# Close copy files declaration cleanly
echo "    # End of Casper VIA S48 proprietary blobs" >> "${OUTPUT_MK}"

echo "[+] Successfully generated ${OUTPUT_MK} and ${BOARD_MK}."
